export const title = "How to Check Portrait Monitor Clearance Under a Shelf";
export const metaTitle = "Portrait Monitor Clearance Under a Shelf";
export const metaDescription = "Measure the final portrait position and rotation route before placing a supported monitor beneath a shelf or in a low alcove.";
